set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
select public.test_assert(jsonb_array_length(public.partner_network_quote_catalog())=2,'manager catalog uses real products');
select public.partner_network_release_quote_terms('00000000-0000-4000-8000-000000000201',jsonb_build_object('request_id','00000000-0000-4000-8000-000000000301','expected_revision',0,'remuneration_mode','price_difference','valid_until',current_date+14,'commercial_terms','EXW, packaging included','reason','Test release','lines',jsonb_build_array(jsonb_build_object('product_id','test-tea','variant_weight','','unit','kg','min_qty',10,'max_qty',500,'base_price',100000))));
select public.test_assert(jsonb_array_length(public.partner_network_quote_proposals(null))=1,'manager sees release');
select public.test_error($q$select public.partner_network_release_quote_terms('00000000-0000-4000-8000-000000000201','{"request_id":"00000000-0000-4000-8000-000000000301","expected_revision":0}'::jsonb)$q$,'quote_release_already_exists');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',false);
select public.test_assert(public.partner_network_quote_proposals(null)='[]','other partner cannot see private basis');
select public.test_error($q$select public.partner_network_quote_proposals('00000000-0000-4000-8000-000000000101')$q$,'partner_not_approved');
select public.test_error($q$select public.partner_network_propose_quote('00000000-0000-4000-8000-000000000301','{}')$q$,'partner_quote_not_found');
select public.test_error('select public.partner_network_quote_catalog()','manager_required');
select public.test_error('select public.partner_network_price_difference_terms(''test'')','permission denied');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.test_assert(jsonb_array_length(public.partner_network_quote_proposals(null))=1,'own terms visible');
select public.test_error($q$select public.partner_network_propose_quote('00000000-0000-4000-8000-000000000301','{"expected_revision":1,"lines":[{"product_id":"test-tea","unit":"kg","qty":500,"price":110000}],"discount_percent":10}')$q$,'partner_quote_below_floor');
select public.test_error($q$select public.partner_network_propose_quote('00000000-0000-4000-8000-000000000301','{"expected_revision":1,"lines":[{"product_id":"test-tea","unit":"kg","qty":501,"price":110000}]}')$q$,'invalid_partner_quote_line');
select public.test_error($q$select public.partner_network_propose_quote('00000000-0000-4000-8000-000000000301','{"expected_revision":1,"lines":[{"product_id":"test-tea","unit":"pcs","qty":500,"price":110000}]}')$q$,'invalid_partner_quote_line');
select public.test_error($q$select public.partner_network_propose_quote('00000000-0000-4000-8000-000000000301','{"expected_revision":1,"partner_id":"forged","lines":[]}')$q$,'invalid_partner_quote');
select public.partner_network_propose_quote('00000000-0000-4000-8000-000000000301','{"expected_revision":1,"lines":[{"product_id":"test-tea","unit":"kg","qty":500,"price":110000}],"discount_percent":0,"note":"Test proposal"}');
select public.test_error($q$select public.partner_network_propose_quote('00000000-0000-4000-8000-000000000301','{"expected_revision":1,"lines":[]}')$q$,'partner_quote_changed');
select public.test_error($q$select public.partner_network_review_quote_proposal('00000000-0000-4000-8000-000000000301','approve','{"expected_revision":2,"reason":"Self approval"}')$q$,'manager_required');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
select public.partner_network_review_quote_proposal('00000000-0000-4000-8000-000000000301','approve','{"expected_revision":2,"reason":"Test approve"}');
select public.test_assert(public.partner_network_review_quote_proposal('00000000-0000-4000-8000-000000000301','approve','{"expected_revision":2,"reason":"Test retry"}')='quote-partner-00000000000040008000000000000301','approval retry idempotent');
reset role;
select public.test_assert((select total=55000000 and partner_account_id='buyer-a' and note='' and position('base_price' in lines::text)=0 and terms='EXW, packaging included' from public.trade_quotes where id='quote-partner-00000000000040008000000000000301'),'buyer quote has selling only and buyer account');
select public.test_error($q$update public.trade_quotes set total=1 where id='quote-partner-00000000000040008000000000000301'$q$,'partner_quote_version_immutable');
update public.trade_quotes set status='accepted' where id='quote-partner-00000000000040008000000000000301';
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
select public.convert_trade_quote_to_order('quote-partner-00000000000040008000000000000301','Test manager');
select public.convert_trade_quote_to_order('quote-partner-00000000000040008000000000000301','Test retry');
reset role;
select public.test_assert((select count(*)=1 from public.orders),'existing conversion idempotent');
select public.test_assert((select count(*)=1 from public.partner_network_order_links where referral_id='00000000-0000-4000-8000-000000000201'),'quote conversion preserves source attribution');
select public.test_assert((select not(public.partner_network_price_difference_terms(id)->>'valid')::boolean from public.orders),'prepaid pending fulfilment cannot settle price difference');
update public.orders set status='completed';
select public.test_assert((select (public.partner_network_price_difference_terms(id)->>'base_amount')::numeric=50000000 and (public.partner_network_price_difference_terms(id)->>'valid')::boolean from public.orders),'financial base matches approved quantity');
update public.orders set lines=jsonb_set(lines,'{0,qty}','250') where true;
select public.test_assert((select (public.partner_network_price_difference_terms(id)->>'base_amount')::numeric=25000000 and (public.partner_network_price_difference_terms(id)->>'valid')::boolean from public.orders),'reduced fulfilled quantity scales base');
update public.orders set lines=jsonb_set(lines,'{0,qty}','501') where true;
select public.test_assert((select not(public.partner_network_price_difference_terms(id)->>'valid')::boolean from public.orders),'increased quantity requires review');
update public.orders set lines=jsonb_set(lines,'{0,unit}','"pcs"') where true;
select public.test_assert((select not(public.partner_network_price_difference_terms(id)->>'valid')::boolean from public.orders),'unit changes invalidate finance');
update public.orders set status='cancelled' where true;
select public.test_assert((select not(public.partner_network_price_difference_terms(id)->>'valid')::boolean from public.orders),'cancellation invalidates finance');
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
select public.test_error($q$select public.partner_network_release_quote_terms('00000000-0000-4000-8000-000000000201','{"request_id":"00000000-0000-4000-8000-000000000302","expected_revision":3,"supersedes_id":"00000000-0000-4000-8000-000000000301"}')$q$,'converted_quote_immutable');
-- A separate, unconverted offer can be replaced without rewriting history.
select public.partner_network_release_quote_terms('00000000-0000-4000-8000-000000000201',jsonb_build_object('request_id','00000000-0000-4000-8000-000000000302','expected_revision',0,'remuneration_mode','commission','valid_until',current_date+14,'commercial_terms','Test public conditions','reason','Separate offer','lines',jsonb_build_array(jsonb_build_object('product_id','test-tea','unit','kg','min_qty',10,'max_qty',500,'base_price',100000))));
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.partner_network_propose_quote('00000000-0000-4000-8000-000000000302','{"expected_revision":1,"lines":[{"product_id":"test-tea","unit":"kg","qty":10,"price":110000}]}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
select public.partner_network_review_quote_proposal('00000000-0000-4000-8000-000000000302','approve','{"expected_revision":2,"reason":"Test approve"}');
select public.test_error($q$select public.partner_network_release_quote_terms('00000000-0000-4000-8000-000000000201','{"request_id":"00000000-0000-4000-8000-000000000303","expected_revision":2,"supersedes_id":"00000000-0000-4000-8000-000000000302"}')$q$,'partner_quote_changed');
select public.partner_network_release_quote_terms('00000000-0000-4000-8000-000000000201',jsonb_build_object('request_id','00000000-0000-4000-8000-000000000303','expected_revision',3,'supersedes_id','00000000-0000-4000-8000-000000000302','remuneration_mode','price_difference','valid_until',current_date+14,'commercial_terms','Revised public conditions','reason','New base approved','lines',jsonb_build_array(jsonb_build_object('product_id','test-tea','unit','kg','min_qty',10,'max_qty',500,'base_price',95000))));
reset role;
select public.test_assert((select status='revoked' and base_lines->0->>'base_price'='100000' from public.partner_network_quote_terms where id='00000000-0000-4000-8000-000000000302'),'superseded base retained');
select public.test_assert((select status='expired' and total=1100000 from public.trade_quotes where id='quote-partner-00000000000040008000000000000302'),'superseded quote expires preserving customer history');
select public.test_error($q$update public.trade_quotes set status='accepted' where id='quote-partner-00000000000040008000000000000302'$q$,'partner_quote_not_open');
update public.partner_network_quote_terms set valid_until=current_date-1 where id='00000000-0000-4000-8000-000000000303';
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.test_error($q$select public.partner_network_propose_quote('00000000-0000-4000-8000-000000000303','{"expected_revision":1,"lines":[]}')$q$,'partner_quote_not_open');
reset role;
update public.partner_network_partners set status='disabled' where id='00000000-0000-4000-8000-000000000101';
set role authenticated;
select public.test_error('select public.partner_network_quote_proposals(null)','partner_not_approved');
select public.test_error($q$select public.partner_network_propose_quote('00000000-0000-4000-8000-000000000303','{"expected_revision":1,"lines":[]}')$q$,'partner_not_approved');
reset role;
select public.test_assert(not has_function_privilege('anon','public.partner_network_propose_quote(uuid,jsonb)','execute'),'anonymous proposal execution denied');
select public.test_assert(not has_table_privilege('authenticated','public.partner_network_quote_terms','UPDATE'),'no partner or staff table writes');
